bool isLeapYear(int year)
{
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

unitTests:
TEST("ordinary leap years") { CHECK(isLeapYear(2024)); CHECK(isLeapYear(1996)); }
TEST("ordinary years") { CHECK(!isLeapYear(2023)); CHECK(!isLeapYear(2026)); }
TEST("century years that are not leap years") { CHECK(!isLeapYear(1900)); CHECK(!isLeapYear(2100)); }
TEST("century years that are leap years") { CHECK(isLeapYear(2000)); CHECK(isLeapYear(1600)); }

